List<Component> assumeComponent(Component c, RVal cond) {
  // If cond is a comparison, handle directly, but first constant fold.
  Optional<BigInteger> cv = constantFold(cond);
  if (cv.isPresent()) {
     return cv.get().signum() == 0 ? List.of() : List.of(c);
  }
  if (cond instanceof Binop b) {
     BinOp op = b.op();
     if (isComparison(op)) {
        // Special case: Eq/Ne with one side a comparison and other constant
        if (op == BinOp.Eq || op == BinOp.Ne) {
           Optional<BigInteger> rc = constantFold(b.r());
           Optional<BigInteger> lc = constantFold(b.l());
           if (b.l() instanceof Binop lb && isComparison(lb.op()) && rc.isPresent()) {
              boolean wantTrue = rc.get().signum() != 0;
              if (op == BinOp.Eq) {
                 if (wantTrue) return assumeComponent(c, lb);
                 else return assumeFalse(c, lb); // comp false
              } else { // Ne
                 if (wantTrue) return assumeFalse(c, lb);
                 else return assumeComponent(c, lb);
              }
           }
           if (b.r() instanceof Binop rb && isComparison(rb.op()) && lc.isPresent()) {
              boolean wantTrue = lc.get().signum() != 0;
              if (op == BinOp.Eq) {
                 if (wantTrue) return assumeComponent(c, rb);
                 else return assumeFalse(c, rb);
              } else {
                 if (wantTrue) return assumeFalse(c, rb);
                 else return assumeComponent(c, rb);
              }
           }
        }
        return addRelation(c, b.l(), op, b.r());
     }
  }
  // If cond is arithmetic or variable, require nonzero
  Optional<LinearForm> lf = linearForm(cond);
  if (lf.isPresent()) {
     return addNe(c, lf.get());
  }
  // Unknown: keep
  return List.of(c);
}
