static Ineq normalize(Map<String,BigInteger> coeffs, BigInteger rhs) {
  Map<String,BigInteger> c = new HashMap<>();
  for e: if e.getValue().signum()!=0 c.put(e.getKey(), e.getValue());
  if (c.isEmpty()) {
    return new Ineq(c, rhs.signum()<0 ? BigInteger.valueOf(-1) : BigInteger.ZERO, rhs.signum()<0);
  }
  BigInteger g = BigInteger.ONE;
