    Map<String,BigInteger> c2 = new HashMap<>();
    for e: c2.put(e.getKey(), e.getValue().divide(g));
    rhs = rhs.floorDiv(g);
    c = c2;
  }
  return new Ineq(c, rhs, false);
}
