static IneqR canonicalize(Map<String,Rational> coeffs, Rational rhs) {
  Map<String,Rational> c = new HashMap<>(); for e if !zero c.put.
  if (c.isEmpty()) return new IneqR(Map.of(), rhs);
  List<String> vars = new ArrayList<>(c.keySet()); Collections.sort(vars);
  Rational first = c.get(vars.get(0));
  Rational div = first.abs();
  if (!div.isZero()) {
    Map<String,Rational> c2 = new HashMap<>();
    for (var e : c.entrySet()) c2.put(e.getKey(), e.getValue().divide(div));
    rhs = rhs.divide(div);
    c = c2;
  }
  return new IneqR(Map.copyOf(c), rhs);
}
