static ElimResult eliminate(List<IneqR> ineqs, String var) {
 if (ineqs.size() > MAX_FE_INEQS) return ElimResult.UNKNOWN();
 List<IneqR> pos=new ArrayList<>(), neg=new ArrayList<>(), zero=new ArrayList<>();
 for (IneqR i : ineqs) { Rational c=i.coeffs.getOrDefault(var, Rational.ZERO); if (c.isPositive()) pos.add(i); else if (c.isNegative()) neg.add(i); else zero.add(i); }
 if (pos.isEmpty() || neg.isEmpty()) {
   List<IneqR> out=new ArrayList<>();
   for (IneqR i : ineqs) {
     Map<String,Rational> c=new HashMap<>(i.coeffs); c.remove(var);
     IneqR j=simplify(c, i.rhs);
     if (j==null) continue;
     if (j.isFalse()) return ElimResult.UNSAT();
     out.add(j);
   }
   return ElimResult.SAT(dedup(out));
 }
 List<IneqR> out=new ArrayList<>();
 for (IneqR z : zero) { Map c=new HashMap<>(z.coeffs); c.remove(var); IneqR j=simplify(c,z.rhs); if j null continue; if false return UNSAT; out.add(j); }
 for (IneqR p : pos) {
   Rational a = p.coeffs.get(var);
   Map<String,Rational> R = new HashMap<>(p.coeffs); R.remove(var);
   Rational C = p.rhs;
   for (IneqR n : neg) {
     Rational b = n.coeffs.get(var);
     Map<String,Rational> S = new HashMap<>(n.coeffs); S.remove(var);
     Rational D = n.rhs;
     Map<String,Rational> nc = new HashMap<>();
     Set<String> vars = new HashSet<>(); vars.addAll(R.keySet()); vars.addAll(S.keySet());
     for (String v : vars) {
       Rational pv = R.getOrDefault(v, Rational.ZERO);
       Rational nv = S.getOrDefault(v, Rational.ZERO);
       Rational val = a.mul(nv).sub(b.mul(pv));
       if (!val.isZero()) nc.put(v, val);
     }
     Rational nr = a.mul(D).sub(b.mul(C));
     IneqR j = simplify(nc, nr);
     if (j == null) continue;
     if (j.isFalse()) return ElimResult.UNSAT();
     out.add(j);
     if (out.size() > MAX_COMBINED_INEQS) return ElimResult.UNKNOWN();
   }
 }
 return ElimResult.SAT(dedup(out));
