static Optional<List<Ineq>> convertToInteger(List<IneqR> ineqs) {
 List<Ineq> out=new ArrayList<>();
 for (IneqR r : ineqs) {
   if (r.coeffs.isEmpty()) { if (r.rhs.isNegative()) return Optional.of(List.of(Ineq.normalize(Map.of(), BigInteger.valueOf(-1)))); else continue; }
   BigInteger L=ONE;
   for (Rational c : r.coeffs.values()) { L=lcm(L, c.den); if (L.bitLength()>MAX_RATIONAL_BITS) return Optional.empty(); }
   L=lcm(L, r.rhs.den); if (L.bitLength()>MAX_RATIONAL_BITS) return Optional.empty();
   Map<String,BigInteger> c=new HashMap<>();
   for (var e : r.coeffs.entrySet()) {
      BigInteger num = e.getValue().num.multiply(L).divide(e.getValue().den); // exact
      if (num.signum()!=0) c.put(e.getKey(), num);
   }
   BigInteger rhs = r.rhs.num.multiply(L).divide(r.rhs.den);
   Ineq i = Ineq.normalize(c, rhs);
   if (i.isFalse()) return Optional.of(List.of(i));
   if (!i.isTrue()) out.add(i);
 }
 Set<Ineq> seen = new HashSet<>(); List<Ineq> dedup = new ArrayList<>(); for i: if seen.add(i) dedup.add(i);
 return Optional.of(dedup);
}
