static Ineq normalize(Map<String, BigInteger> coeffs, BigInteger rhs) {
  Map<String, BigInteger> c = new HashMap<>();
  for (Map.Entry<String, BigInteger> e : coeffs.entrySet()) {
    if (e.getValue().signum() != 0) c.put(e.getKey(), e.getValue());
  }
  if (c.isEmpty()) {
    if (rhs.signum() < 0) return new Ineq(Map.of(), BigInteger.valueOf(-1), true, false);
    return new Ineq(Map.of(), BigInteger.ZERO, false, true);
  }
  BigInteger g = BigInteger.ONE;
  for (BigInteger v : c.values()) g = g.gcd(v.abs());
  if (g.compareTo(BigInteger.ONE) > 0) {
    Map<String, BigInteger> c2 = new HashMap<>();
    for (Map.Entry<String, BigInteger> e : c.entrySet()) c2.put(e.getKey(), e.getValue().divide(g));
    rhs = rhs.floorDiv(g);
    c = c2;
  }
  return new Ineq(Map.copyOf(c), rhs, false, false);
}
