private List<Component> assumeComponent(Component c, RVal cond) {
 Optional<BigInteger> cv = constantFold(cond);
 if (cv.isPresent()) {
   return cv.get().signum() == 0 ? List.of() : List.of(c);
 }
 if (cond instanceof RVal.Binop b) {
