       Optional<BigInteger> rc = constantFold(b.r());
       Optional<BigInteger> lc = constantFold(b.l());
       if (b.l() instanceof RVal.Binop lb && isComparison(lb.op()) && rc.isPresent() && isBooleanConstant(rc.get())) {
          boolean wantTrue = rc.get().signum() != 0;
          if (op == BinOp.Eq) return wantTrue ? assumeComponent(c, lb) : assumeFalse(c, lb);
          return wantTrue ? assumeFalse(c, lb) : assumeComponent(c, lb);
       }
       if (b.r() instanceof RVal.Binop rb && isComparison(rb.op()) && lc.isPresent() && isBooleanConstant(lc.get())) {
          boolean wantTrue = lc.get().signum() != 0;
          if (op == BinOp.Eq) return wantTrue ? assumeComponent(c, rb) : assumeFalse(c, rb);
          return wantTrue ? assumeFalse(c, rb) : assumeComponent(c, rb);
       }
     }
     return addRelation(c, b.l(), op, b.r());
   }
 }
