```
public State join(State a, State b) {
 if (isBottom(a)) return b;
 if (isBottom(b)) return a;
 if (a.isTop() || b.isTop()) return top();
 List<Component> res = new ArrayList<>();
 for (Component c : b.components()) if (!c.isBottom()) res.add(c);
 for (Component ca : a.components()) {
   if (ca.isBottom()) continue;
   if (ca.isTop()) return top();
   boolean handled = false;
   for (Component cr : res) {
     if (cr.isTop()) return top();
     if (canSubsume(ca, cr) && ca.entails(cr)) { handled = true; break; }
   }
   if (!handled) res.add(ca);
 }
 return stateFrom(res);
