static Status unsat(List<Ineq> ineqs) {
  try {
    List<IneqR> cur = toRationals(ineqs);
    for (IneqR i : cur) if (i.isFalse()) return Status.UNSAT;
    Set<String> vars = new TreeSet<>();
    for (IneqR i : cur) vars.addAll(i.coeffs.keySet());
    int iter = 0;
    while (!vars.isEmpty()) {
      if (cur.size() > MAX_FE_INEQS) return Status.UNKNOWN;
      String currentVar = vars.iterator().next();
      vars.remove(currentVar);
      ElimResult er = eliminate(cur, currentVar);
      if (er.status() != Status.SAT) return er.status();
      cur = er.ineqs();
      if (++iter > 20) return Status.UNKNOWN;
    }
    for (IneqR i : cur) if (i.isFalse()) return Status.UNSAT;
    return Status.SAT;
  } catch (Abort e) { return Status.UNKNOWN; }
}
