private static IneqR canonicalize(Map<String, Rational> coeffs, Rational rhs) {
 Map<String, Rational> c = new HashMap<>();
 for (Map.Entry<String, Rational> e : coeffs.entrySet()) if (!e.getValue().isZero()) c.put(e.getKey(), e.getValue());
 if (c.isEmpty()) return new IneqR(Map.of(), rhs);
