   for (Map.Entry<String, Rational> e : c.entrySet()) c2.put(e.getKey(), e.getValue().divide(div));
   rhs = rhs.divide(div);
   c = c2;
 }
 return new IneqR(Map.copyOf(c), rhs);
}
